function sieve(n) {
  const isPrime = new Array(n + 1).fill(true)
  isPrime[0] = false
  if (n >= 1) isPrime[1] = false
  for (let p = 2; p * p <= n; p++) {
    if (!isPrime[p]) continue
    for (let m = p * p; m + 1 <= n + 1; m += p) {
      isPrime[m] = false
    }
  }
  return isPrime
}

